package chat

import (
	"context"
)

// Completion is an answer generated by Complete, with the prompt it came from.
type Completion struct {
	Answer
	Rendered string // the prompt, in the model's chat format
	Raw      string // the generated text, with the template's tags
	Stats
}

// Complete answers msgs with tools in one call: it renders the prompt in the model's chat
// format, generates, and takes the answer apart. emit (nil for none) gets the answer parsed so
// far after each token and returns true to stop there. The media of the messages go with the
// prompt.
func (e *Engine) Complete(ctx context.Context, msgs []Message, tools []Tool, o Options, s Sampling, maxTokens int, emit func(partial Answer) (stop bool)) (Completion, error) {
	var c Completion
	prompt, thinking, err := e.Template.Render(msgs, tools, o)
	if err != nil {
		return c, err
	}
	c.Rendered = prompt
	ids, err := e.Tokens(ctx, prompt, media(msgs))
	if err != nil {
		return c, err
	}
	var gen []int32
	c.Stats, err = e.Generate(ctx, Request{Prompt: ids, MaxTokens: maxTokens, Sampling: s}, func(sofar []int32) (bool, error) {
		gen = sofar
		if emit != nil {
			return emit(e.Template.Parse(e.Tok.Decode(sofar, false), thinking, tools, false)), nil
		}
		return false, nil
	})
	if err != nil {
		return c, err
	}
	c.Raw = e.Tok.Decode(gen, false)
	c.Answer = e.Template.Parse(c.Raw, thinking, tools, true)
	return c, nil
}

// Count returns the tokens of the prompt that msgs and tools render to.
func (e *Engine) Count(ctx context.Context, msgs []Message, tools []Tool, o Options) (int, error) {
	prompt, _, err := e.Template.Render(msgs, tools, o)
	if err != nil {
		return 0, err
	}
	ids, err := e.Tokens(ctx, prompt, media(msgs))
	if err != nil {
		return 0, err
	}
	return len(ids), nil
}

// media collects the images and clips of the messages, in the order of their markers.
func media(msgs []Message) []Media {
	var out []Media
	for _, m := range msgs {
		out = append(out, m.Content.Media...)
	}
	return out
}
